/* v2.9: every look change costs stars. One price per key (GAME_CONTENT.prices); facts for clothing are built
   from the teaching card (made + who). Badge texts no longer promise a free tunic: the badge unlocks a dye. */
(function () {
  var P = GAME_CONTENT.prices;
  GAME_CONTENT.markets.forEach(function (m) {
    m.items.forEach(function (x) {
      x.price = P[x.key];
      if (!x.fact) x.fact = (x.made ? "Made of: " + x.made + " " : "") + (x.who ? "Who wore it: " + x.who : "");
    });
  });
  (GAME_CONTENT.sections || []).forEach(function (s) {
    if (s.badge && s.badge.desc) s.badge.desc = s.badge.desc.replace(/ Your tunic (turns|becomes|shines) .*$/, " Unlocks a new tunic dye at the market.");
  });
  if (GAME_CONTENT.final && GAME_CONTENT.final.badge) GAME_CONTENT.final.badge.desc = GAME_CONTENT.final.badge.desc.replace(/ Your tunic (turns|becomes|shines) .*$/, " Unlocks the royal-gold tunic dye at the market.");
})();
